      return AgentCli(
        config: AgentCliConfig(
          model: Model(
            id: 'start-model',
            api: 'test-api',
            provider: 'test-provider',
            baseUrl: 'https://example.test',
            contextWindow: 100000,
            maxTokens: 4096,
          ),
          apiKey: '',
          env: env,
          sessionRoot: '/sessions',
          sessionName: sessionName,
          customProviders: registry,
          secureKeys: keyCache,
        ),
        io: freshIo(),
        streamFunction: _singleTextResponse('ok'),
      );
    }

    test(
