    const iraKeyName = 'FA_KEY_API_KIMI_COM_IRA_1';
    const kimiMeKeyName = 'FA_KEY_API_KIMI_COM_KIMI_ME';

    /// Two saved providers sharing ONE modelId and ONE endpoint — the
