    CustomProviderRegistry twinRegistry() => CustomProviderRegistry([
      CustomProviderEntry(
        name: 'ira-1',
        apiType: 'kimi',
        baseUrl: kimiUrl,
        modelId: 'k3-256k',
        keyName: iraKeyName,
      ),
      CustomProviderEntry(
