      // would): the zai catalog kind keeps the test network-free.
      await saveFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work',
        providerKind: 'zai',
        modelId: 'glm-5.3-flash',
        baseUrl: null,
